import React from 'react';
import { Link, useLocation } from 'react-router-dom';

const Navbar = ({ isAuthenticated, onSignOut }) => {
  const location = useLocation();
  const navItems = [
    { label: 'Browse', to: '/' },
    { label: 'Post Item', to: '/sell' },
    { label: 'Dashboard', to: '/dashboard' }
  ];

  return (
    <header className="site-navbar">
      <div className="nav-inner">
        <Link to="/" className="brand-link">
          <span className="brand-icon">C</span>
          <span className="brand-text">CampusMart</span>
        </Link>

        <Link to="/wishlist" className="nav-link" style={{ position: 'relative' }}>
  ❤️ Wishlist
  {wishlistCount > 0 && (
    <span style={{
      position: 'absolute',
      top: '-4px',
      right: '-4px',
      background: 'linear-gradient(135deg, #ec4899, #f43f5e)',
      color: 'white',
      borderRadius: '50%',
      width: '18px',
      height: '18px',
      fontSize: '11px',
      fontWeight: '800',
      display: 'grid',
      placeItems: 'center'
    }}>
      {wishlistCount}
    </span>
  )}
</Link>

        <nav className="nav-menu">
          {navItems.map((item) => (
            <Link
              key={item.to}
              to={item.to}
              className={`nav-link ${location.pathname === item.to ? 'active' : ''}`}
            >
              {item.label}
            </Link>
          ))}

          {!isAuthenticated ? (
            <Link to="/login" className="nav-cta">
              Login
            </Link>
          ) : (
            <button type="button" className="nav-cta nav-cta-small" onClick={onSignOut}>
              Sign Out
            </button>
          )}
        </nav>
      </div>
    </header>
  );
};

export default Navbar;
